static const cheat_db_index_t *cheat_db_find(const char *game_id)
{
  if (!game_id) return NULL;

  int lo = 0, hi = CHEAT_DB_GAME_COUNT - 1;
  while (lo <= hi) {
    int mid = (lo + hi) / 2;
    int cmp = strcmp(game_id, cheat_db_index[mid].game_id);
    if (cmp == 0)
      return &cheat_db_index[mid];
    else if (cmp < 0)
      hi = mid - 1;
    else
      lo = mid + 1;
  }
  return NULL;
}
